// Service worker, generated by scripts/stamp-build.mjs from scripts/sw.template.js.
// Network first for everything (a stale build is worse than a slow load), with
// the cache as the fallback so the page opens offline; the whole build is
// precached on install and old caches are dropped on activate. Cross-origin
// requests (nodes, Esplora, relays, price API) are never cached.
const BUILD = '__BUILD__';
const CACHE = 'btc-alph-swap-' + BUILD;
const ASSETS = __ASSETS__;

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE).then((c) => c.addAll(ASSETS)).then(() => self.skipWaiting()));
});
self.addEventListener('activate', (event) => {
  event.waitUntil(caches.keys().then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k)))).then(() => self.clients.claim()));
});
self.addEventListener('fetch', (event) => {
  const url = new URL(event.request.url);
  if (event.request.method !== 'GET' || url.origin !== self.location.origin) return;
  event.respondWith(
    fetch(event.request).then((res) => {
      if (res.ok) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put(event.request, copy)); }
      return res;
    }).catch(() => caches.match(event.request, { ignoreSearch: true }).then((hit) => hit || (url.pathname.endsWith('/') || url.pathname.endsWith('.html') ? caches.match('./index.html') : undefined)))
  );
});
